using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Services {
 public sealed partial class DesktopService {
  public void OpenControlCenter(string page){if(!System.Text.RegularExpressions.Regex.IsMatch(page,@"^[a-z-]+$"))throw new ArgumentException("화면 이름을 확인하세요.");Launch(new System.Diagnostics.ProcessStartInfo(Path.Combine(Root,"bin","GUNT.ControlCenter.exe"),Quote(Root)+" "+page){UseShellExecute=true});}
  public CommandStore CommandsConfig(){var s=Local("commands",()=>new CommandStore());if(s==null||s.SchemaVersion!=1||s.Aliases==null||s.Recent==null||s.Favorites==null)throw new InvalidDataException("명령 설정을 확인하세요.");return s;}
  public CommandEntry[] Commands(){var list=new List<CommandEntry>();foreach(var a in new[]{new[]{"settings","GUNT 설정","settings 설정","page","overview"},new[]{"developer","개발 세팅","dev 개발 developer","page","developer-setup"},new[]{"dock","Dock 설정","dock 도크","page","dock"},new[]{"monitor-settings","시스템 모니터 설정","monitor settings","page","monitor"},new[]{"session-start","개발 세션 시작","start session dev","session",""},new[]{"projects","프로젝트","project projects 폴더","page","projects"},new[]{"sessions","개발 세션","session 세션","page","development-sessions"},new[]{"wsl-env","WSL 환경","wsl ubuntu 환경","page","wsl-environments"},new[]{"sensors","센서 상태 확인","sensor 온도","page","sensors"},new[]{"diagnostics","진단 및 복구","diagnostic recovery","page","diagnostics"},new[]{"profiles","작업공간 프로필","profiles focus gaming","page","profiles"},new[]{"quick-panel","빠른 패널","quick panel","panel","quick-panel"},new[]{"monitor-show","시스템 모니터 표시","monitor show 모니터","desktop","monitor-show"},new[]{"monitor-hide","시스템 모니터 숨김","monitor hide 모니터","desktop","monitor-hide"},new[]{"wallpaper-pause","배경화면 일시정지","wallpaper pause 배경 정지","desktop","wallpaper-pause"},new[]{"wallpaper-play","배경화면 재생","wallpaper play 배경 재생","desktop","wallpaper-play"},new[]{"layout","레이아웃 복원","layout restore 배치","desktop","layout-restore"}})list.Add(new CommandEntry{Id=a[0],Name=a[1],Aliases=a[2],Action=a[3],Value=a[4]});foreach(var a in new[]{new[]{"ai","기본 AI CLI","ai 기본 에이아이"},new[]{"codex","WSL + Codex","cx codex 코덱스"},new[]{"opencode","WSL + OpenCode","oc opencode 오픈코드"},new[]{"ide","VS Code","code vscode 비주얼"},new[]{"folder","폴더 열기","folder explorer"},new[]{"terminal","터미널 열기","terminal 터미널"}})list.Add(new CommandEntry{Id=a[0],Name=a[1]+" · 현재 프로젝트",Aliases=a[2],Action="developer",Value=a[0]});foreach(var profile in Profiles())list.Add(new CommandEntry{Id="profile:"+profile.Id,Name=profile.Name+" 프로필 미리보기",Aliases=profile.Id+" profile",Action="profile",Value=profile.Id});foreach(var p in Projects()){foreach(string a in new[]{"codex","opencode","ide"})list.Add(new CommandEntry{Id="project:"+p.Id+":"+a,Name=p.Name+" · "+(a=="ide"?"VS Code":a),Aliases=p.Name+" "+a,Action="developer",Value=a,ProjectId=p.Id});}var config=CommandsConfig();foreach(var c in list)c.Favorite=config.Favorites.Contains(c.Id);return list.ToArray();}
  public static int MatchCommand(string query,string text){query=Regex.Replace(query??"",@"\s+","").ToLowerInvariant();text=Regex.Replace(text??"",@"\s+","").ToLowerInvariant();if(query.Length==0)return 1;if(text.StartsWith(query))return 1000-query.Length;if(text.Contains(query))return 500-query.Length;int i=0;foreach(char c in text)if(i<query.Length&&query[i]==c)i++;return i==query.Length?100-query.Length:0;}
  public CommandEntry[] SearchCommands(string query){return SearchCommands(query,Commands(),CommandsConfig());}
  public CommandEntry[] SearchCommands(string query,CommandEntry[] list,CommandStore config){string builtin=query.Trim().ToLowerInvariant();if(builtin=="cx"||builtin=="oc"||builtin=="dev")return list.Where(c=>c.Id==(builtin=="cx"?"codex":builtin=="oc"?"opencode":"developer")).ToArray();string alias=config.Aliases.Keys.FirstOrDefault(a=>a.Equals(query.Trim(),StringComparison.OrdinalIgnoreCase));if(alias!=null)return list.Where(c=>c.Id==config.Aliases[alias]).ToArray();return list.Select(c=>new{Command=c,Score=MatchCommand(query,c.Name+" "+c.Aliases)}).Where(x=>x.Score>0).OrderByDescending(x=>x.Command.Favorite).ThenByDescending(x=>x.Score).ThenBy(x=>{int at=config.Recent.IndexOf(x.Command.Id);return at<0?999:at;}).Select(x=>x.Command).Take(60).ToArray();}
  public void SaveAlias(string alias,string commandId){alias=alias.Trim();if(!Regex.IsMatch(alias,@"^[\p{L}\p{N}_-]{1,32}$"))throw new ArgumentException("별칭은 글자·숫자·밑줄·하이픈 1–32자로 입력하세요.");var all=Commands();if(!all.Any(x=>x.Id==commandId))throw new ArgumentException("실제 명령을 선택하세요.");var s=CommandsConfig();if(s.Aliases.Keys.Any(x=>x.Equals(alias,StringComparison.OrdinalIgnoreCase))||all.Any(c=>(c.Aliases??"").Split(' ').Any(a=>a.Equals(alias,StringComparison.OrdinalIgnoreCase))||c.Id.Equals(alias,StringComparison.OrdinalIgnoreCase)))throw new ArgumentException("이미 사용 중인 별칭입니다. 덮어쓰지 않았습니다.");s.Aliases.Add(alias,commandId);SaveLocal("commands",s);}
  public void DeleteAlias(string alias){var s=CommandsConfig();s.Aliases.Remove(alias);SaveLocal("commands",s);}
  public void FavoriteCommand(string id){if(!Commands().Any(x=>x.Id==id))throw new ArgumentException("명령을 확인하세요.");var s=CommandsConfig();if(!s.Favorites.Remove(id))s.Favorites.Add(id);SaveLocal("commands",s);}
  public string ExecuteCommand(CommandEntry command){var c=Commands().FirstOrDefault(x=>x.Id==command.Id);if(c==null)throw new ArgumentException("명령을 다시 선택하세요.");string result;if(c.Action=="developer"){var p=String.IsNullOrEmpty(c.ProjectId)?ActiveProject():Projects().First(x=>x.Id==c.ProjectId);result=LaunchDeveloper(p,c.Value);}else if(c.Action=="profile"){Action("profile-preview",c.Value);result="프로필 미리보기를 열었습니다.";}else if(c.Action=="desktop"){Action(c.Value);result="데스크톱 동작 요청: "+c.Name;}else throw new ArgumentException("이 명령은 제어 센터의 화면 이동으로 처리합니다.");RememberCommand(c.Id);return result;}
  public void RememberCommand(string id){var s=CommandsConfig();s.Recent.Remove(id);s.Recent.Insert(0,id);s.Recent=s.Recent.Take(30).ToList();SaveLocal("commands",s);}
 }
}
